void FillRandom(std::vector<float> &data, unsigned int seed) {
  if (seed == 0) {
    seed = static_cast<unsigned int>(time(NULL));
  }
  std::cout << "Current srand seed: " << seed << std::endl;
  std::srand(seed); // make random inputs reproducible
  for (unsigned int t = 0; t < data.size(); ++t) {
    data[t] =
        static_cast<float>(std::rand()) / static_cast<float>(RAND_MAX) - 0.5f;
  }
}

