#include "audio2face/error.h"
#include <gtest/gtest.h>

TEST(TestCoreError, Code) {
  // These are generic codes, they typically work.
  {
    const std::error_code errorCode = nva2f::ErrorCode::eCudaEventCreateError;
    const std::string errorMessage = errorCode.message();
    ASSERT_EQ(errorMessage, "eCudaEventCreateError");
  }

  // These are specific for fields, they used to crash.
  {
    const std::error_code errorCode = nva2f::ErrorCode::eNotANumber;
    const std::string errorMessage = errorCode.message();
    ASSERT_EQ(errorMessage, "eNotANumber");
  }
  {
    const std::error_code errorCode = nva2f::ErrorCode::eOutOfRange;
    const std::string errorMessage = errorCode.message();
    ASSERT_EQ(errorMessage, "eOutOfRange");
  }
}

